"""Render the human parameter catalog from the authoritative JSON registry."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render(schema):
    lines = [
        '# Scientific parameter reference', '',
        'Generated by `tools/update_parameter_reference.py` from',
        f'`bdam_parameter_schema.json` ({schema["version"]}). Do not edit the tables by hand.',
        'See [PARAMETERS.md](PARAMETERS.md) for overrides, arrays, automatic values and migration.', '',
        'The units are meters and days. Each row is an accepted scientific field; study',
        'capacity, retention and the MATLAB executable belong to execution settings.',
        'Automatic values are resolved after shared settings and case overrides.', '',
        'General interactions: layer-property arrays match `n_layers`; the dam leakage',
        'layer count cannot exceed it. Automatic boundary K follows `K_constant`.',
        'UZF water contents must satisfy residual < saturated, with initial/ET contents',
        'within their permitted ranges. Monthly arrays are January–December. Geometry',
        'must fit the channel/meander and contain integer cell counts. Preparation can',
        'reject geometric combinations even when individual fields meet their bounds.', '',
        'Registry defaults and the MATLAB defaults mirror must remain consistent.',
        'Removed intermediate width/depth/preview controls are not accepted; river pool',
        'initial depth is fixed at 0.10 m and installation conserves inherited volume.', '',
    ]
    lines += ['## Automatic defaults', '']
    for name, description in schema.get('dependent_defaults', {}).items():
        lines.append(f'- `{name}`: {description}.')
    lines.append('')
    groups = {}
    for name, spec in schema['parameters'].items():
        group = name.split('.')[0] if '.' in name else 'General'
        groups.setdefault(group, []).append((name, spec))
    for group, entries in groups.items():
        lines += [f'## {group}', '', '| Field | Default | Type / shape | Units | Constraints |',
                  '| --- | --- | --- | --- | --- |']
        for name, spec in entries:
            default = 'automatic' if spec['default'] is None else '`'+json.dumps(spec['default'], separators=(', ', ': '))+'`'
            kind = spec['type']
            if 'length' in spec:
                kind += f' ({spec["length"]} entries)'
            bounds = []
            for key, sign in [('minimum', '≥'), ('exclusive_minimum', '>'), ('maximum', '≤')]:
                if key in spec:
                    bounds.append(f'{sign} {spec[key]}')
            if 'enum' in spec:
                bounds.append(', '.join('`'+v+'`' for v in spec['enum']))
            if spec['automatic']:
                bounds.append('`null` allowed')
            units = 'field-specific' if spec['type'] == 'records' else '—' if spec['type'] == 'string' else spec['units']
            lines.append(f'| `{name}` | {default} | {kind} | {units} | {"; ".join(bounds) or "See preparation constraints"} |')
        lines.append('')
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--schema', type=Path, default=ROOT/'bdam_parameter_schema.json')
    parser.add_argument('--output', type=Path, default=ROOT/'PARAMETER_REFERENCE.md')
    parser.add_argument('--check', action='store_true', help='fail if the catalog needs regeneration')
    args = parser.parse_args()
    content = render(json.loads(args.schema.read_text()))
    if args.check:
        if not args.output.is_file() or args.output.read_text() != content:
            parser.error('Parameter reference is out of date; regenerate it.')
    else:
        args.output.write_text(content)


if __name__ == '__main__':
    main()
